(() => {
  if (window.__drAlexTrackingLoaded) return;
  window.__drAlexTrackingLoaded = true;

  const PRODUCT_NAME = "Implante de lentes premium";
  const BASE_MESSAGE = "Olá, vim da página e gostaria de mais informações sobre implante de lentes premium";

  const configs = {
    sp: {
      phone: "5511993971230",
      product_slug: "lentes_premium_sp",
      lp_name: "LP Lentes Premium SP",
      lp_view: "lp_view_lentes_premium_sp",
      whatsapp_event: "whatsapp_lentes_premium_sp",
      ads_conversion: "AW-960830346/We2zCIH5xcwcEIq3lMoD",
      testimonials_view: "testimonials_view_lentes_premium_sp",
      video: {
        start: "video_start_lentes_premium_sp",
        25: "video_25_lentes_premium_sp",
        50: "video_50_lentes_premium_sp",
        75: "video_75_lentes_premium_sp",
        complete: "video_complete_lentes_premium_sp"
      },
      scroll: {
        25: "scroll_25_lentes_premium_sp",
        50: "scroll_50_lentes_premium_sp",
        75: "scroll_75_lentes_premium_sp",
        90: "scroll_90_lentes_premium_sp"
      }
    },
    feira: {
      phone: "557581498753",
      product_slug: "lentes_premium_feira",
      lp_name: "LP Lentes Premium Feira de Santana",
      lp_view: "lp_view_lentes_premium_feira",
      whatsapp_event: "whatsapp_lentes_premium_feira",
      ads_conversion: "AW-960830346/6QXLCLSCxswcEIq3lMoD",
      testimonials_view: "testimonials_view_lentes_premium_feira",
      video: {
        start: "video_start_lentes_premium_feira",
        25: "video_25_lentes_premium_feira",
        50: "video_50_lentes_premium_feira",
        75: "video_75_lentes_premium_feira",
        complete: "video_complete_lentes_premium_feira"
      },
      scroll: {
        25: "scroll_25_lentes_premium_feira",
        50: "scroll_50_lentes_premium_feira",
        75: "scroll_75_lentes_premium_feira",
        90: "scroll_90_lentes_premium_feira"
      }
    }
  };

  const qs = new URLSearchParams(location.search);
  const debugEnabled = qs.get("debug_mode") === "true";
  const debugLog = (...args) => {
    if (debugEnabled) console.log("[DrAlexTracking]", ...args);
  };

  const pageKey = document.body.dataset.lpMarket || (/\/feira-de-santana\/?/i.test(location.pathname) ? "feira" : "sp");
  const pageConfig = configs[pageKey] || configs.sp;
  const sourceMap = { facebook: "Facebook", instagram: "Instagram", meta: "Facebook/Instagram", google: "Google", tiktok: "TikTok" };
  const trackedParams = ["utm_source", "utm_medium", "utm_campaign", "utm_content", "utm_term", "gclid", "fbclid", "wbraid", "gbraid", "msclkid", "ttclid"];
  const videoState = window.__drAlexVideoState || {};
  window.__drAlexVideoState = videoState;

  debugLog("Tracking loaded");
  debugLog("Page config", { pageKey, product_slug: pageConfig.product_slug, lp_name: pageConfig.lp_name });

  const getCookie = (name) => {
    const match = document.cookie.match(new RegExp("(^| )" + name + "=([^;]+)"));
    return match ? decodeURIComponent(match[2]) : "";
  };

  const getDeviceType = () => /Mobi|Android|iPhone|iPad|iPod/i.test(navigator.userAgent) ? "mobile" : "desktop";
  const getOS = () => {
    const ua = navigator.userAgent;
    if (/Windows/i.test(ua)) return "Windows";
    if (/Android/i.test(ua)) return "Android";
    if (/iPhone|iPad|iPod/i.test(ua)) return "iOS";
    if (/Mac OS/i.test(ua)) return "macOS";
    if (/Linux/i.test(ua)) return "Linux";
    return "unknown";
  };
  const getBrowser = () => {
    const ua = navigator.userAgent;
    if (/Edg\//.test(ua)) return "Edge";
    if (/OPR\//.test(ua)) return "Opera";
    if (/Chrome\//.test(ua)) return "Chrome";
    if (/Safari\//.test(ua) && !/Chrome\//.test(ua)) return "Safari";
    if (/Firefox\//.test(ua)) return "Firefox";
    return "unknown";
  };

  const createEventId = (name) => `${name}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

  const commonData = (eventId = "") => {
    const data = {
      product_name: PRODUCT_NAME,
      product_slug: pageConfig.product_slug,
      lp_name: pageConfig.lp_name,
      page_url: location.href,
      page_path: location.pathname,
      page_title: document.title,
      referrer: document.referrer || "",
      device_type: getDeviceType(),
      device_os: getOS(),
      browser: getBrowser(),
      screen_width: screen.width,
      screen_height: screen.height,
      viewport_width: window.innerWidth,
      viewport_height: window.innerHeight,
      timestamp: new Date().toISOString()
    };
    if (debugEnabled) data.debug_mode = true;
    trackedParams.forEach((key) => {
      const value = qs.get(key);
      if (value) data[key] = value;
    });
    const fbp = getCookie("_fbp");
    const fbc = getCookie("_fbc");
    if (fbp) data._fbp = fbp;
    if (fbc) data._fbc = fbc;
    if (eventId) data.event_id = eventId;
    return data;
  };

  window.drAlexTrackEvent = (eventName, eventData = {}) => {
    const payload = { ...commonData(eventData.event_id), ...eventData };
    if (window.gtag) window.gtag("event", eventName, { ...payload, transport_type: "beacon" });
    if (window.fbq) window.fbq("trackCustom", eventName, payload, payload.event_id ? { eventID: payload.event_id } : undefined);
    debugLog("Event fired", eventName, payload);
  };

  const getOrigin = () => {
    const source = (qs.get("utm_source") || "").trim().toLowerCase();
    if (!source) return "";
    return sourceMap[source] || source;
  };

  const buildWhatsappUrl = () => {
    const origem = getOrigin();
    const finalMessage = origem ? `${BASE_MESSAGE}. Vi o anúncio no ${origem}.` : BASE_MESSAGE;
    return `https://api.whatsapp.com/send?phone=${pageConfig.phone}&text=${encodeURIComponent(finalMessage)}`;
  };

  const inferLocation = (link) => {
    if (link.dataset.whatsappLocation) return link.dataset.whatsappLocation;
    if (link.classList.contains("whatsapp-float")) return "sticky";
    if (link.closest("header")) return "header";
    if (link.closest("#inicio")) return "hero";
    if (link.closest(".assessment")) return "avaliacao";
    if (link.closest(".lens-banner")) return "lentes";
    if (link.closest("#como-funciona")) return "meio";
    if (link.closest(".facility,.facility-gallery")) return "estrutura";
    if (link.closest(".final-cta")) return "final";
    if (link.closest("footer")) return "footer";
    return "meio";
  };

  const cleanText = (el) => (el.innerText || el.getAttribute("aria-label") || "whatsapp").replace(/\s+/g, " ").trim();

  const normaliseVideoMeta = (source) => {
    const fallbackIndex = Array.from(document.querySelectorAll(".video-card")).indexOf(source) + 1;
    return {
      video_index: Number(source?.dataset?.videoIndex || fallbackIndex || 0),
      video_id: source?.dataset?.videoId || `depoimento_${fallbackIndex || 1}`,
      video_title: source?.dataset?.videoTitle || `Depoimento ${fallbackIndex || 1}`,
      video_location: source?.dataset?.videoLocation || "depoimentos"
    };
  };

  const getVideoState = (videoId) => {
    const id = videoId || "depoimento_1";
    videoState[id] = videoState[id] || {};
    return videoState[id];
  };

  const videoDataFromMeta = (meta, video = null, percent = 0) => ({
    video_index: Number(meta.video_index || 0),
    video_id: meta.video_id || "",
    video_title: meta.video_title || "",
    video_location: meta.video_location || "depoimentos",
    video_duration: video && Number.isFinite(video.duration) ? Math.round(video.duration) : 0,
    video_current_time: video && Number.isFinite(video.currentTime) ? Math.round(video.currentTime) : 0,
    video_percent: percent,
    product_name: PRODUCT_NAME,
    product_slug: pageConfig.product_slug,
    lp_name: pageConfig.lp_name
  });

  const videoData = (video, percent = 0) => videoDataFromMeta(normaliseVideoMeta(video), video, percent);

  const trackVideoEvent = (eventName, meta, video = null, percent = 0) => {
    window.drAlexTrackEvent(eventName, {
      ...videoDataFromMeta(meta, video, percent),
      event_id: createEventId(eventName)
    });
    debugLog("Video event fired", eventName, { video_id: meta.video_id, percent });
  };

  const trackVideoStart = (source) => {
    const meta = normaliseVideoMeta(source);
    const state = getVideoState(meta.video_id);
    if (state.start) return;
    state.start = true;
    trackVideoEvent(pageConfig.video.start, meta, source?.tagName === "VIDEO" ? source : null, 0);
  };

  const trackVideoMark = (video, mark) => {
    const meta = normaliseVideoMeta(video);
    const state = getVideoState(meta.video_id);
    if (state[mark]) return;
    state[mark] = true;
    trackVideoEvent(pageConfig.video[mark], meta, video, mark);
  };

  const trackVideoComplete = (video) => {
    const meta = normaliseVideoMeta(video);
    const state = getVideoState(meta.video_id);
    if (state.complete) return;
    state.complete = true;
    trackVideoEvent(pageConfig.video.complete, meta, video, 100);
    debugLog("Video completed", meta.video_id);
  };

  const checkVideoProgress = (video, forceComplete = false) => {
    if (!video) return;
    trackVideoStart(video);
    if (!Number.isFinite(video.duration) || video.duration <= 0) return;
    const percent = Math.floor((video.currentTime / video.duration) * 100);
    debugLog("Video progress percent", { video_id: video.dataset.videoId, percent });
    [25, 50, 75].forEach((mark) => {
      if (percent >= mark) trackVideoMark(video, mark);
    });
    if (forceComplete || percent >= 95 || video.ended === true) trackVideoComplete(video);
  };

  const bindVideoTracking = (video) => {
    if (!video) return;
    if (!video.dataset.videoId) {
      const parentCard = video.closest?.(".video-card");
      const meta = normaliseVideoMeta(parentCard || video);
      video.dataset.videoIndex = video.dataset.videoIndex || String(meta.video_index);
      video.dataset.videoId = video.dataset.videoId || meta.video_id;
      video.dataset.videoTitle = video.dataset.videoTitle || meta.video_title;
      video.dataset.videoLocation = video.dataset.videoLocation || meta.video_location;
    }
    if (video.dataset.videoTrackingBound === "1") {
      checkVideoProgress(video);
      return;
    }
    video.dataset.videoTrackingBound = "1";
    ["play", "playing"].forEach((eventName) => video.addEventListener(eventName, () => {
      trackVideoStart(video);
      checkVideoProgress(video);
    }));
    ["timeupdate", "progress", "seeked", "pause"].forEach((eventName) => video.addEventListener(eventName, () => checkVideoProgress(video)));
    video.addEventListener("ended", () => checkVideoProgress(video, true));
    debugLog("Video tracking bound", videoData(video, 0));
    checkVideoProgress(video);
  };

  window.drAlexBindVideoTracking = bindVideoTracking;

  document.addEventListener("click", (event) => {
    const card = event.target.closest?.(".video-card");
    if (!card) return;
    trackVideoStart(card);
  }, true);

  const setupVideoTracking = () => {
    document.querySelectorAll("video").forEach(bindVideoTracking);
    const videoObserver = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        mutation.addedNodes.forEach((node) => {
          if (node.nodeType !== 1) return;
          if (node.matches?.("video")) bindVideoTracking(node);
          node.querySelectorAll?.("video").forEach(bindVideoTracking);
        });
      });
    });
    videoObserver.observe(document.body, { childList: true, subtree: true });
  };

  const setupTestimonialsView = () => {
    const section = document.querySelector("#depoimentos");
    if (!section || !("IntersectionObserver" in window)) return;
    let fired = false;
    const testimonialsObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (fired || !entry.isIntersecting || entry.intersectionRatio < 0.5) return;
        fired = true;
        window.drAlexTrackEvent(pageConfig.testimonials_view, {
          event_id: createEventId(pageConfig.testimonials_view)
        });
        testimonialsObserver.unobserve(section);
      });
    }, { threshold: [0.5] });
    testimonialsObserver.observe(section);
  };

  window.drAlexTrackWhatsappClick = (link, event) => {
    if (event) event.preventDefault();
    if (link.dataset.trackingBusy === "1") return;
    link.dataset.trackingBusy = "1";
    setTimeout(() => { link.dataset.trackingBusy = "0"; }, 1200);

    const eventId = createEventId(pageConfig.whatsapp_event);
    const whatsappUrl = buildWhatsappUrl();
    link.href = whatsappUrl;

    const payload = {
      ...commonData(eventId),
      product_name: PRODUCT_NAME,
      product_slug: pageConfig.product_slug,
      lp_name: pageConfig.lp_name,
      conversion_type: "whatsapp",
      event_id: eventId,
      button_location: inferLocation(link),
      button_text: cleanText(link)
    };

    if (window.gtag) window.gtag("event", pageConfig.whatsapp_event, { ...payload, transport_type: "beacon" });
    if (window.fbq) window.fbq("trackCustom", pageConfig.whatsapp_event, payload, { eventID: eventId });

    let redirected = false;
    const redirect = () => {
      if (redirected) return;
      redirected = true;
      window.location.href = whatsappUrl;
    };

    if (window.gtag) {
      window.gtag("event", "conversion", {
        send_to: pageConfig.ads_conversion,
        value: 0,
        currency: "BRL",
        event_callback: redirect,
        event_timeout: 700
      });
      setTimeout(redirect, 800);
    } else {
      redirect();
    }
  };

  const setupWhatsappLinks = () => {
    const links = document.querySelectorAll('a[href*="api.whatsapp.com/send"], a[href*="wa.me/"]');
    links.forEach((link) => {
      if (link.dataset.whatsappTrackingBound === "1") return;
      link.href = buildWhatsappUrl();
      link.dataset.whatsappLocation = inferLocation(link);
      link.dataset.whatsappTrackingBound = "1";
      link.addEventListener("click", (event) => window.drAlexTrackWhatsappClick(link, event));
    });
    debugLog("WhatsApp links mapped", links.length);
  };

  const firedScroll = {};
  let scrollRafPending = false;

  const getScrollInfo = () => {
    const scrollTop = Math.max(window.pageYOffset || 0, document.documentElement.scrollTop || 0, document.body.scrollTop || 0);
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight;
    const documentHeight = Math.max(
      document.body.scrollHeight,
      document.documentElement.scrollHeight,
      document.body.offsetHeight,
      document.documentElement.offsetHeight,
      document.body.clientHeight,
      document.documentElement.clientHeight
    );
    const maxScroll = Math.max(documentHeight - viewportHeight, 1);
    const isAtBottom = scrollTop + viewportHeight >= documentHeight - 8;
    const scrollPercent = isAtBottom ? 100 : Math.min(100, Math.round((scrollTop / maxScroll) * 100));
    return { scrollTop, viewportHeight, documentHeight, maxScroll, isAtBottom, scrollPercent };
  };

  const fireScrollThreshold = (threshold) => {
    if (firedScroll[threshold]) return;
    firedScroll[threshold] = true;
    window.drAlexTrackEvent(pageConfig.scroll[threshold], {
      event_id: createEventId(pageConfig.scroll[threshold]),
      scroll_depth: threshold,
      scroll_percent: threshold
    });
    debugLog("Scroll event fired", pageConfig.scroll[threshold]);
  };

  const checkScroll = () => {
    scrollRafPending = false;
    const info = getScrollInfo();
    debugLog("Scroll percent atual", info.scrollPercent, info);
    [25, 50, 75, 90].forEach((threshold) => {
      if (info.scrollPercent >= threshold || info.isAtBottom) fireScrollThreshold(threshold);
    });
  };

  const scheduleScrollCheck = () => {
    if (scrollRafPending) return;
    scrollRafPending = true;
    requestAnimationFrame(checkScroll);
  };

  window.drAlexTrackingStatus = () => ({
    loaded: true,
    pageKey,
    product_slug: pageConfig.product_slug,
    lp_name: pageConfig.lp_name,
    gtag: typeof window.gtag,
    fbq: typeof window.fbq,
    whatsappLinks: document.querySelectorAll('a[href*="api.whatsapp.com/send"], a[href*="wa.me/"]').length,
    videoCards: document.querySelectorAll(".video-card").length,
    videos: document.querySelectorAll("video").length,
    debug: debugEnabled
  });

  window.drAlexForceScrollTest = () => {
    [25, 50, 75, 90].forEach((threshold) => {
      window.drAlexTrackEvent(pageConfig.scroll[threshold], {
        event_id: createEventId(pageConfig.scroll[threshold]),
        scroll_depth: threshold,
        scroll_percent: threshold,
        test_event: true
      });
    });
  };

  window.drAlexForceVideoTest = () => {
    const source = document.querySelector("video") || document.querySelector(".video-card") || {};
    const meta = normaliseVideoMeta(source);
    trackVideoEvent(pageConfig.video.start, meta, source.tagName === "VIDEO" ? source : null, 0);
    [25, 50, 75].forEach((mark) => trackVideoEvent(pageConfig.video[mark], meta, source.tagName === "VIDEO" ? source : null, mark));
    trackVideoEvent(pageConfig.video.complete, meta, source.tagName === "VIDEO" ? source : null, 100);
  };

  window.drAlexTrackEvent(pageConfig.lp_view, { event_id: createEventId(pageConfig.lp_view) });
  setupWhatsappLinks();
  setupTestimonialsView();
  setupVideoTracking();
  ["scroll", "resize", "orientationchange", "load", "pageshow", "touchmove"].forEach((eventName) => {
    window.addEventListener(eventName, scheduleScrollCheck, { passive: true });
  });
  scheduleScrollCheck();
})();